#!/usr/bin/env python3
"""Build explicit prerecorded compatibility controls, not a procedural MP4 encoder."""
import base64,hashlib,json,re,subprocess
from pathlib import Path
from urllib.parse import quote
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[1]
F=ROOT/'fixtures/marketplace-probe';F.mkdir(parents=True,exist_ok=True)
js="""<!doctype html><meta charset=utf-8><title>ghoulballs JS probe</title><style>body{margin:0;background:#130b25;color:#fff;font:16px monospace}canvas{width:100%;image-rendering:pixelated}</style><canvas width=128 height=128></canvas><p id=status>JavaScript did not run</p><script>const c=document.querySelector('canvas'),g=c.getContext('2d');let count=0;function tick(t){g.fillStyle='#130b25';g.fillRect(0,0,128,128);g.fillStyle='#ff78cf';g.beginPath();g.arc(64+40*Math.sin(t*Math.PI/1000),64,16,0,7);g.fill();document.querySelector('#status').textContent='JavaScript running: '+(++count);requestAnimationFrame(tick)}requestAnimationFrame(tick)</script>"""
css="""<!doctype html><meta charset=utf-8><title>ghoulballs CSS probe</title><style>body{margin:0;background:#130b25;color:#fff;font:16px monospace}.ball{width:32px;height:32px;border-radius:50%;background:#ff78cf;position:absolute;top:48px;left:48px;animation:move 2s infinite linear}@keyframes move{0%,100%{transform:translateX(-40px)}50%{transform:translateX(40px)}}</style><div class=ball></div><p>CSS animation, no JavaScript</p>"""
hosted=ROOT/'mint-page/dist/probe/player.html';hosted.parent.mkdir(parents=True,exist_ok=True);hosted.write_text(js)
(F/'html-js.html').write_text(js);(F/'html-css.html').write_text(css)
frames=[]
for x in [5,12,20,12]:
 im=Image.new('RGB',(32,32),'#130b25');ImageDraw.Draw(im).ellipse((x-4,12,x+4,20),fill='#ff78cf');frames.append(im)
frames[0].save(F/'image-control.gif',save_all=True,append_images=frames[1:],duration=500,loop=0)
large_prefix="<!doctype html><meta charset=utf-8><title>600KB HTML probe</title><style>body{background:#130b25;color:white}p{position:fixed;top:0}</style><p>600,000 byte HTML control, no JavaScript</p><!--"
large=large_prefix+'A'*(600000-len(large_prefix)-3)+'-->'
assert len(large.encode())==600000
image='data:image/gif;base64,'+base64.b64encode((F/'image-control.gif').read_bytes()).decode()
metadata={'name':'ghoulballs probe #11 - Cheap 600KB HTML','description':'Compatibility control. Compact prerecorded padding; no artwork rendering work in this read.','image':image,'animation_url':'data:text/html,'+quote(large,safe='-._~'),'attributes':[{'trait_type':'Probe','value':'Cheap 600KB HTML'}]}
uri='data:application/json;base64,'+base64.b64encode(json.dumps(metadata,separators=(',',':')).encode()).decode()
(F/'large-html.uri').write_text(uri)
outputs={'HTML_JS':js.encode(),'HTML_CSS':css.encode(),'GIF':(F/'image-control.gif').read_bytes(),'MP4':(F/'native-control.mp4').read_bytes()}
source='// SPDX-License-Identifier: MIT\npragma solidity ^0.8.30;\n\n// GENERATED by scripts/build_probe_fixtures.py. Prerecorded diagnostic controls.\nlibrary ProbeFixtures {\n'
for name,data in outputs.items():source+=f'    function {name.lower()}() internal pure returns (bytes memory) {{ return hex"{data.hex()}"; }}\n'
raw=uri.encode()
run=max(re.finditer(rb'(?:QUFB){16,}',raw),key=lambda m:m.end()-m.start())
start=run.start();span=(run.end()-start)//32*32
head=raw[:start];tail=raw[start+span:]
source+=f'    function large_size() internal pure returns (uint256) {{ return {len(raw)}; }}\n'
# Feed the public fixture through stdin to avoid the OS argument-length limit.
hash_value=subprocess.check_output(['cast','keccak'],input=raw).decode().strip()
source+=f'    function large_hash() internal pure returns (bytes32) {{ return {hash_value}; }}\n'
source+=f'    function large_uri() internal pure returns (bytes memory output) {{ output = new bytes({len(raw)}); bytes memory head = hex"{head.hex()}"; bytes memory tail = hex"{tail.hex()}"; assembly ("memory-safe") {{ let dst := add(output, 32) mcopy(dst, add(head,32), mload(head)) let begin := add(dst, {start}) let end := add(begin, {span}) for {{let p := begin}} lt(p,end) {{p := add(p,32)}} {{mstore(p,0x{(b"QUFB"*8).hex()})}} mcopy(end,add(tail,32),mload(tail)) }} }}\n'
source+='}\n';(ROOT/'src/probes/ProbeFixtures.sol').write_text(source)
(F/'manifest.json').write_text(json.dumps({'purpose':'Prerecorded compatibility controls; not a Solidity MP4 encoder','html_bytes':600000,'large_uri_bytes':len(uri),'large_uri_compact_header_bytes':len(head),'large_uri_repeat_bytes':span,'large_uri_compact_tail_bytes':len(tail),'sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(F.iterdir()) if p.name!='manifest.json'}},indent=2)+'\n')
print('Prepared controls:',len(uri),'large URI bytes; compact padding preserves the exact bytes without data-storage deployments')
